(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-977":{scenario:{company:"Ngan Tung Land Registration Office",supervisor:{name:"Trịnh Văn Hòa",role:{vi:"Giám đốc Chi nhánh Văn phòng Đăng ký Đất đai",en:"Branch Director, Land Registration Office"}},ref_code:"DK-6093",title:{vi:"Đúng loại đất. Đúng diện tích đo đạc.",en:"Right land use code. Surveyed area only."},brief:{vi:"Đây là tình huống đào tạo. Bạn thẩm tra hồ sơ đăng ký biến động DK-6093 của một thửa đất ở thuộc phường Ngân Tùng (đơn vị hành chính đô thị, mô phỏng). Tọa độ các đỉnh theo biên bản đo đạc (m, hệ VN-2000 rút gọn): A(0;0), B(24;0), C(26.5;18), D(1.5;16). Tờ khai của người sử dụng đất ghi 432 m2, gồm cả phần đang sử dụng lấn ra ngõ chung. Sửa mã loại đất và diện tích thửa trên bản nháp, rồi lập báo cáo có căn cứ (số liệu mô phỏng).",en:"This is a training scenario. You are verifying change registration file DK-6093 for a residential parcel in Ngan Tung ward (an urban administrative unit, simulated). Vertex coordinates from the survey record (m, reduced VN-2000): A(0;0), B(24;0), C(26.5;18), D(1.5;16). The land user's declaration states 432 m2, including a strip used by encroaching on the shared alley. Correct the land use code and the parcel area in the draft, then write an evidence-based report (simulated data)."},reference_title:{vi:"Trích lục & biên bản đo đạc đã duyệt · DK-6093",en:"Approved cadastral extract & survey record · DK-6093"},fields:[{id:"LAND_CODE",label:{vi:"Mã loại đất",en:"Land use code"},initial:"ONT",expected:"ODT",choices:["ONT","ODT","CLN"],reference:"Trích lục bản đồ địa chính",hint:{vi:"Đất ở tại đô thị và đất ở tại nông thôn có ký hiệu khác nhau, xác định theo đơn vị hành chính nơi có thửa đất.",en:"Urban and rural residential land use different codes, set by the administrative unit where the parcel lies."}},{id:"AREA_M2",label:{vi:"Diện tích thửa (m2)",en:"Parcel area (m2)"},initial:"432",expected:"414.5",reference:"Biên bản đo đạc thửa đất",ref_value:{vi:"A(0;0), B(24;0), C(26.5;18), D(1.5;16) theo thứ tự trên đường bao",en:"A(0;0), B(24;0), C(26.5;18), D(1.5;16) in boundary order"},hint:{vi:"Tính diện tích đa giác từ tọa độ đỉnh bằng công thức Gauss, không lấy số theo tờ khai.",en:"Compute the polygon area from vertex coordinates with the shoelace formula, not from the declaration."}}],sop32:{vi:"Diện tích thửa = 1/2 x |tổng (x_i x y_(i+1) - x_(i+1) x y_i)| theo thứ tự đỉnh trên đường bao khép kín; diện tích ghi vào hồ sơ là diện tích đo đạc, không gồm phần lấn chiếm.",en:"Parcel area = 1/2 x |sum of (x_i x y_(i+1) - x_(i+1) x y_i)| over the closed boundary vertices in order; the recorded area is the surveyed area, excluding encroached land."},context:{label:"LIS / DK-6093",metrics:[{label:{vi:"Hệ tọa độ",en:"Coordinate system"},value:"VN-2000"},{label:{vi:"Số đỉnh thửa",en:"Parcel vertices"},value:"4"},{label:{vi:"Diện tích theo tờ khai",en:"Declared area"},value:"432 m2"}]},crisis:{vi:"Một người môi giới nhắn: “Em cứ giữ 432 m2 như tờ khai, phần ngõ chung ai đo lại đâu, chủ nhà sẽ hậu tạ. Ký sớm giúp anh để kịp công chứng hợp đồng chuyển nhượng tuần này.”",en:"A broker messages you: “Just keep 432 m2 as declared, nobody will re-measure the shared alley and the owner will thank you generously. Sign it soon so the sale contract can be notarized this week.”"},options:{safe:{vi:"Ghi mã loại đất và diện tích theo kết quả đo đạc, từ chối mọi lợi ích, lập biên bản phần lấn ngõ chung; báo giám đốc chi nhánh và chuyển cơ quan có thẩm quyền xem xét theo quy định.",en:"Record the land code and the surveyed area, refuse any benefit and document the alley encroachment; inform the branch director and refer it to the competent authority."},shortcut:{vi:"Giữ diện tích 432 m2 theo tờ khai cho kịp công chứng, điều chỉnh sau nếu có tranh chấp.",en:"Keep the declared 432 m2 so notarization can proceed and adjust later if a dispute arises."},wait:{vi:"Treo hồ sơ, không trả lời, chờ chủ đất tự giải quyết với hàng xóm.",en:"Leave the file pending without reply until the owner settles it with the neighbors."}},questions:{vi:["Vì sao thửa đất mang mã ODT? Trình bày cách tính diện tích từ tọa độ và phần chênh so với tờ khai.","Việc ghi nhận phần lấn ngõ chung vào diện tích thửa gây rủi ro pháp lý gì, và bạn xử lý lời đề nghị “hậu tạ” ra sao?"],en:["Why does the parcel take code ODT? Show how you computed the area from coordinates and the gap with the declaration.","What legal risks arise from recording the encroached alley in the parcel area, and how do you handle the offered reward?"]},hints:{vi:["Xác định đơn vị hành chính của thửa đất trước khi chọn ký hiệu loại đất ở.","Liệt kê tọa độ theo đúng thứ tự đường bao rồi áp dụng công thức ở SOP mục 3.2.","Đọc lại SOP mục 4.2: hồ sơ địa chính phải phản ánh đúng thực địa; mọi lợi ích được đề nghị phải từ chối và báo cáo."],en:["Identify the parcel's administrative unit before choosing the residential land code.","List the coordinates in boundary order and apply the formula in SOP 3.2.","Re-read SOP 4.2: cadastral records must match the ground; refuse and report any offered benefit."]}},learning:{summary:{vi:"Chuyên viên quản lý đất đai và địa chính thẩm tra hồ sơ đăng ký đất đai, cấp Giấy chứng nhận, đăng ký biến động, cập nhật bản đồ và cơ sở dữ liệu địa chính. Nghề bảo vệ quyền hợp pháp của người sử dụng đất và lợi ích công, đòi hỏi nắm chắc pháp luật đất đai, kỹ thuật đo đạc, GIS và liêm chính công vụ.",en:"A land administration and cadastral officer verifies land registration files, issues certificates, records changes and updates cadastral maps and databases. The role protects land users' lawful rights and the public interest, and requires solid land law, surveying techniques, GIS and public integrity."},responsibilities:{vi:["Thẩm tra hồ sơ đăng ký lần đầu, đăng ký biến động và cấp đổi Giấy chứng nhận.","Đối chiếu ranh giới, diện tích, mục đích sử dụng với bản đồ địa chính và quy hoạch.","Kiểm tra kết quả đo đạc, tính diện tích và xử lý chênh lệch so với giấy tờ.","Cập nhật cơ sở dữ liệu địa chính, chỉnh lý bản đồ và lưu trữ hồ sơ.","Phối hợp xác minh nguồn gốc đất, xử lý lấn chiếm và trả lời phản ánh của người dân."],en:["Verify first-time registration, change registration and certificate reissue files.","Check boundaries, area and land use against the cadastral map and land use plans.","Review survey results, compute areas and resolve gaps with the papers.","Update the cadastral database, revise maps and archive records.","Verify land origin, handle encroachment and answer citizens' feedback."]},competencies:[{name:{vi:"Pháp luật đất đai",en:"Land law"},desc:{vi:"Áp dụng đúng điều kiện cấp Giấy chứng nhận, đăng ký biến động và phân loại đất.",en:"Apply certificate conditions, change registration and land classification correctly."}},{name:{vi:"Đo đạc & bản đồ",en:"Surveying & mapping"},desc:{vi:"Đọc biên bản đo, tọa độ VN-2000, tính diện tích và kiểm tra sai số.",en:"Read survey records and VN-2000 coordinates, compute areas and check tolerances."}},{name:{vi:"GIS & cơ sở dữ liệu",en:"GIS & databases"},desc:{vi:"Chỉnh lý bản đồ số, đồng bộ dữ liệu không gian và thuộc tính.",en:"Edit digital maps and keep spatial and attribute data in sync."}},{name:{vi:"Thẩm tra hồ sơ",en:"File verification"},desc:{vi:"Phát hiện mâu thuẫn giữa tờ khai, giấy tờ nguồn gốc và kết quả đo đạc.",en:"Spot conflicts between declarations, origin documents and survey results."}},{name:{vi:"Liêm chính công vụ",en:"Public integrity"},desc:{vi:"Từ chối lợi ích, ghi nhận trung thực thực địa và báo cáo hành vi tiêu cực.",en:"Refuse benefits, record the ground truthfully and report misconduct."}}],knowledge:{vi:["Luật Đất đai số 31/2024/QH15: phân loại đất, đăng ký đất đai, cấp Giấy chứng nhận và quyền của người sử dụng đất.","Nghị định 101/2024/NĐ-CP về điều tra cơ bản đất đai, đăng ký, cấp Giấy chứng nhận và hệ thống thông tin đất đai.","Luật Đo đạc và bản đồ số 27/2018/QH14, hệ tọa độ quốc gia VN-2000 và quy định kỹ thuật bản đồ địa chính.","Ký hiệu loại đất trên bản đồ địa chính như ODT, ONT, LUC, CLN, TMD và cách xác định.","Luật Phòng, chống tham nhũng số 36/2018/QH14 và quy tắc ứng xử của công chức."],en:["Land Law No. 31/2024/QH15: land classification, registration, certificates and land users' rights.","Decree 101/2024/ND-CP on land surveys, registration, certificate issuance and the land information system.","Law on Surveying and Mapping No. 27/2018/QH14, the national VN-2000 datum and cadastral mapping rules.","Cadastral land use codes such as ODT, ONT, LUC, CLN and TMD and how they are assigned.","Anti-Corruption Law No. 36/2018/QH14 and the civil servant code of conduct."]},tools:["Hệ thống thông tin đất đai (LIS)","Phần mềm biên tập bản đồ địa chính","Máy toàn đạc điện tử và GNSS RTK","GIS (QGIS)","Chữ ký số và lưu trữ điện tử"],kpis:{vi:["Tỷ lệ hồ sơ đăng ký giải quyết đúng hạn.","Tỷ lệ hồ sơ phải trả lại do sai sót thẩm tra.","Mức đồng bộ giữa hồ sơ giấy, bản đồ và cơ sở dữ liệu địa chính.","Số khiếu nại do sai diện tích hoặc mục đích sử dụng."],en:["Share of registration files resolved on time.","Files returned because of verification errors.","Consistency between paper files, maps and the cadastral database.","Complaints caused by wrong area or land use."]},day:[{time:"08:00",vi:"Nhận hồ sơ chuyển từ bộ phận một cửa, phân loại theo loại thủ tục và thời hạn.",en:"Receive files from the one-stop desk and sort them by procedure and deadline."},{time:"09:30",vi:"Thẩm tra giấy tờ nguồn gốc, đối chiếu bản đồ địa chính và quy hoạch.",en:"Verify origin documents against the cadastral map and land use plan."},{time:"13:30",vi:"Kiểm tra biên bản đo đạc, tính diện tích từ tọa độ và lập phiếu chênh lệch.",en:"Check survey records, compute areas from coordinates and log discrepancies."},{time:"15:30",vi:"Chỉnh lý bản đồ số và cập nhật cơ sở dữ liệu địa chính.",en:"Revise the digital map and update the cadastral database."},{time:"17:00",vi:"Trình ký kết quả, báo cáo hồ sơ vướng mắc cho giám đốc chi nhánh.",en:"Submit results for signature and report problem files to the branch director."}],mistakes:{vi:["Ghi diện tích theo tờ khai thay vì theo kết quả đo đạc thực tế.","Nhầm ký hiệu đất ở đô thị và nông thôn khi thửa đất thuộc phường.","Bỏ qua phần lấn chiếm đất công, hợp thức hóa sai vào Giấy chứng nhận."],en:["Recording the declared area instead of the surveyed one.","Confusing urban and rural residential codes for a parcel in a ward.","Ignoring encroachment on public land and wrongly legalizing it on the certificate."]},career:[{vi:"Cán bộ địa chính cấp xã, phường",en:"Commune or ward cadastral officer"},{vi:"Chuyên viên đăng ký đất đai và địa chính",en:"Land registration and cadastral officer"},{vi:"Trưởng nhóm thẩm tra hồ sơ đất đai",en:"Land file verification lead"},{vi:"Giám đốc Văn phòng Đăng ký Đất đai",en:"Director of a land registration office"}],glossary:[{term:"Thửa đất",vi:"Phần diện tích đất được giới hạn bởi ranh giới xác định trên thực địa hoặc trên hồ sơ.",en:"A land area bounded by limits defined on the ground or in records."},{term:"ODT",vi:"Ký hiệu đất ở tại đô thị trên bản đồ và hồ sơ địa chính.",en:"Cadastral code for urban residential land."},{term:"VN-2000",vi:"Hệ quy chiếu và hệ tọa độ quốc gia Việt Nam dùng cho đo đạc và bản đồ.",en:"Vietnam's national reference and coordinate system for surveying and mapping."},{term:"Đăng ký biến động",vi:"Đăng ký thay đổi về người sử dụng, diện tích, mục đích hoặc quyền đối với thửa đất.",en:"Registering changes to the user, area, use or rights of a parcel."},{term:"Shoelace formula",vi:"Công thức Gauss tính diện tích đa giác từ tọa độ các đỉnh theo thứ tự.",en:"Gauss's formula for polygon area from ordered vertex coordinates."}],quiz:[{q:{vi:"Thửa đất có đỉnh A(0;0), B(10;0), C(8;6), D(0;6) theo thứ tự. Diện tích là bao nhiêu?",en:"A parcel has vertices A(0;0), B(10;0), C(8;6), D(0;6) in order. What is its area?"},options:{vi:["60 m2","48 m2","54 m2","108 m2"],en:["60 m2","48 m2","54 m2","108 m2"]},answer:2,explain:{vi:"Tổng tích chéo = 0 + 60 + 48 + 0 = 108; diện tích = 108 / 2 = 54 m2.",en:"Cross-product sum = 0 + 60 + 48 + 0 = 108; area = 108 / 2 = 54 m2."}},{q:{vi:"Thửa đất ở nằm trong một phường. Ký hiệu loại đất đúng là gì?",en:"A residential parcel lies in an urban ward. What is the correct land use code?"},options:{vi:["ODT","ONT","CLN","LUC"],en:["ODT","ONT","CLN","LUC"]},answer:0,explain:{vi:"ODT là đất ở tại đô thị; ONT là đất ở tại nông thôn.",en:"ODT is urban residential land; ONT is rural residential land."}},{q:{vi:"Hệ VN-2000 được dùng để làm gì trong địa chính?",en:"What is VN-2000 used for in cadastral work?"},options:{vi:["Mã hóa loại đất","Hệ quy chiếu, tọa độ quốc gia cho đo đạc và bản đồ","Phần mềm quản lý hồ sơ","Tiêu chuẩn lưu trữ giấy"],en:["Coding land use types","The national reference and coordinate system for surveys and maps","A file management software","A paper archiving standard"]},answer:1,explain:{vi:"VN-2000 là hệ quy chiếu và tọa độ quốc gia, nền tảng cho bản đồ địa chính.",en:"VN-2000 is the national reference and coordinate system underlying cadastral maps."}},{q:{vi:"Môi giới đề nghị “hậu tạ” để giữ diện tích theo tờ khai, gồm cả phần lấn ngõ chung. Bạn làm gì?",en:"A broker offers a reward to keep the declared area that includes the encroached alley. What do you do?"},options:{vi:["Đồng ý vì chênh lệch nhỏ","Giữ số tờ khai nhưng không nhận tiền","Chờ hàng xóm khiếu nại","Ghi đúng diện tích đo đạc, từ chối lợi ích và báo cáo"],en:["Agree since the gap is small","Keep the declared figure but refuse the money","Wait for neighbors to complain","Record the surveyed area, refuse the benefit and report it"]},answer:3,explain:{vi:"Hồ sơ địa chính phải đúng thực địa; nhận lợi ích để làm sai là vi phạm pháp luật về phòng, chống tham nhũng.",en:"Cadastral records must match the ground; taking benefits to falsify them breaks anti-corruption law."}}],tools_en:["Land information system (LIS)","Cadastral map editing software","Electronic total station and GNSS RTK","GIS (QGIS)","Digital signature and e-archiving"]}}})})(window.KKR);
